// English-mode background: an animated homage to Van Gogh's "The Starry Night" (1889, public domain) —
// a swirling, brush-stroked night sky with haloed stars and a crescent moon, a flame-like cypress and village hills —
// plus original bold-flower / tropical-leaf / hummingbird motifs inspired by Mexican folk art of Frida Kahlo's era.
// Everything is drawn here or in assets/en/*.svg (generated by tools/gen_en_art.py); no painting is copied.
// Loaded lazily by bg.js only when English is first shown.
(() => {
  "use strict";
  const TAU = Math.PI * 2;
  let el, base, anim, bctx, actx, W = 0, H = 0, DPR = 1, M = 1, parts = [], stars = [], moon, vort = [], starSpr, moonSpr;
  const BLUES = ["#9fc3ec", "#c9ddf2", "#6f97d6", "#4f78c4", "#e9dc8c", "#f6f1d2"];

  const HB = (id) => `<svg viewBox="0 0 120 80" aria-hidden="true"><defs><linearGradient id="hbg${id}" x1="0" y1="0" x2="1" y2="1">
<stop offset="0" stop-color="var(--hb1)"/><stop offset="1" stop-color="var(--hb2)"/></linearGradient></defs>
<path d="M28 46 L2 36 L8 46 L1 56 Z" fill="var(--hb2)"/>
<ellipse cx="48" cy="45" rx="25" ry="11" transform="rotate(-14 48 45)" fill="url(#hbg${id})"/>
<path d="M36 50 Q50 58 64 48" stroke="#f3e7c9" stroke-width="3" fill="none" opacity=".55"/>
<circle cx="72" cy="35" r="10.5" fill="var(--hb1)"/>
<path d="M64 40 Q71 50 80 41 Q74 43 66 38 Z" fill="var(--hbt)"/>
<circle cx="75.5" cy="32.5" r="2.1" fill="#fff"/><circle cx="76" cy="32.6" r="1.2" fill="#111"/>
<path d="M82 33 L118 27.5" stroke="#1b1b1b" stroke-width="2.4" stroke-linecap="round"/>
<g class="wing"><path d="M52 38 C42 12 30 2 18 3 C26 14 36 28 50 41 Z" fill="var(--hbw)" stroke="rgba(255,255,255,.5)" stroke-width="1"/>
<path d="M50 38 C40 18 30 10 22 8" stroke="rgba(255,255,255,.45)" stroke-width="1" fill="none"/></g></svg>`;

  function field(x, y) {
    let vx = 1, vy = .38 * Math.sin(x / W * 6 + y / H * 4);
    for (const v of vort) {
      const dx = x - v.x, dy = y - v.y, d = Math.hypot(dx, dy) + 1, g = Math.exp(-(d * d) / (v.r * v.r)), k = v.s * g * 2.4;
      vx += -dy / d * k - dx / d * .3 * g; vy += dx / d * k - dy / d * .3 * g;
    }
    return Math.atan2(vy, vx);
  }
  function glowAt(x, y) { let g = 0; for (const v of vort) { const d = Math.hypot(x - v.x, y - v.y) / v.r; g = Math.max(g, Math.exp(-(d - .75) * (d - .75) * 6)); } return g; }
  function nearLight(x, y) {
    for (const s of stars) if (Math.hypot(x - s.x, y - s.y) < s.r * 1.9) return true;
    return Math.hypot(x - moon.x, y - moon.y) < moon.r * 2.1;
  }

  function makeStarSprite() {
    const n = 128, c = document.createElement("canvas"); c.width = c.height = n; const g = c.getContext("2d"), h = n / 2;
    let gr = g.createRadialGradient(h, h, 0, h, h, h); gr.addColorStop(0, "rgba(255,250,215,1)"); gr.addColorStop(.18, "rgba(250,232,140,.95)");
    gr.addColorStop(.4, "rgba(232,205,95,.35)"); gr.addColorStop(1, "rgba(232,205,95,0)"); g.fillStyle = gr; g.fillRect(0, 0, n, n);
    g.lineCap = "round";
    for (const [rr, col, w] of [[.3, "rgba(255,240,170,.9)", 3.2], [.46, "rgba(240,215,110,.65)", 3], [.62, "rgba(190,210,235,.45)", 2.6], [.8, "rgba(150,185,230,.28)", 2.4]]) {
      g.strokeStyle = col; g.lineWidth = w; const k = Math.round(10 + rr * 22);
      for (let i = 0; i < k; i++) { const a = i / k * TAU + Math.random() * .1; g.beginPath(); g.arc(h, h, rr * h, a, a + TAU / k * .62); g.stroke(); }
    }
    return c;
  }
  function makeMoonSprite() {
    const n = 220, c = document.createElement("canvas"); c.width = c.height = n; const g = c.getContext("2d"), h = n / 2;
    let gr = g.createRadialGradient(h, h, 0, h, h, h); gr.addColorStop(0, "rgba(255,214,110,.75)"); gr.addColorStop(.4, "rgba(240,180,70,.35)"); gr.addColorStop(1, "rgba(240,180,70,0)");
    g.fillStyle = gr; g.fillRect(0, 0, n, n); g.lineCap = "round";
    for (const [rr, col] of [[.42, "rgba(255,215,120,.85)"], [.56, "rgba(246,190,90,.6)"], [.72, "rgba(225,170,80,.35)"], [.88, "rgba(160,170,190,.22)"]]) {
      g.strokeStyle = col; g.lineWidth = 4.5; const k = Math.round(14 + rr * 26);
      for (let i = 0; i < k; i++) { const a = i / k * TAU; g.beginPath(); g.arc(h, h, rr * h, a, a + TAU / k * .7); g.stroke(); }
    }
    // the crescent
    const m = document.createElement("canvas"); m.width = m.height = n; const q = m.getContext("2d");
    q.fillStyle = "#ffd25e"; q.beginPath(); q.arc(h, h, n * .17, 0, TAU); q.fill();
    q.fillStyle = "#f6a623"; q.beginPath(); q.arc(h + 4, h + 3, n * .14, 0, TAU); q.fill();
    q.globalCompositeOperation = "destination-out"; q.beginPath(); q.arc(h + n * .085, h - n * .045, n * .15, 0, TAU); q.fill();
    g.drawImage(m, 0, 0); return c;
  }

  function layout() {
    const mob = W < 700; M = Math.min(W, H) || 1;
    vort = mob ? [{ x: W * .52, y: H * .56, r: M * .42, s: 1.3 }, { x: W * .25, y: H * .74, r: M * .24, s: -1 }]
               : [{ x: W * .44, y: H * .3, r: M * .3, s: 1.4 }, { x: W * .63, y: H * .38, r: M * .18, s: -1.15 }];
    const sb = Math.max(14, Math.min(40, M * .045));
    const P = mob ? [[.1, .08, .7], [.6, .06, .6], [.9, .3, .8], [.14, .44, .8], [.42, .47, .6], [.66, .7, .65], [.88, .78, .55], [.36, .82, .5], [.06, .6, .55]]
                  : [[.1, .14, 1], [.25, .08, .75], [.33, .22, .7], [.56, .1, .9], [.71, .2, .75], [.92, .36, .6], [.17, .44, .7], [.8, .52, .55], [.5, .5, .5], [.04, .32, .55], [.38, .58, .45]];
    stars = P.map(([x, y, s], i) => ({ x: x * W, y: y * H, r: sb * s, ph: i * 1.7, sp: .7 + (i % 4) * .2 }));
    moon = mob ? { x: W * .8, y: H * .55, r: Math.max(34, M * .13) } : { x: W * .87, y: H * .21, r: Math.max(44, Math.min(90, M * .1)) };
  }

  function paintBase() {
    bctx.setTransform(DPR, 0, 0, DPR, 0, 0);
    const gr = bctx.createLinearGradient(0, 0, 0, H);
    gr.addColorStop(0, "#071131"); gr.addColorStop(.5, "#10255f"); gr.addColorStop(.8, "#1a347a"); gr.addColorStop(1, "#122656");
    bctx.fillStyle = gr; bctx.fillRect(0, 0, W, H); bctx.lineCap = "round";
    const N = Math.min(15000, Math.round(W * H / 66));
    const deep = ["#0d1f52", "#15306f", "#1c3c86", "#24489a", "#0a1840", "#2c56a8"], light = ["#5f86c8", "#86a8da", "#b4cbe8", "#d8e4f0", "#3f69b5"], yel = ["#f1d97a", "#e7c55a", "#f8ecb4", "#d8b84c", "#c9d3a0"];
    for (let i = 0; i < N; i++) {
      const x = Math.random() * W, y = Math.random() * H * .9, g = glowAt(x, y), nl = nearLight(x, y);
      const pal = nl && Math.random() < .8 ? yel : (Math.random() < g * .75 ? light : deep);
      const c = pal[(Math.random() * pal.length) | 0], w = 2 + Math.random() * 2.8, st = 5 + Math.random() * 4;
      let px = x, py = y; bctx.beginPath(); bctx.moveTo(px, py);
      for (let k = 0; k < 3; k++) { const a = field(px, py); px += Math.cos(a) * st; py += Math.sin(a) * st; bctx.lineTo(px, py); }
      bctx.globalAlpha = .55 + Math.random() * .4; bctx.strokeStyle = c; bctx.lineWidth = w; bctx.stroke();
      if (Math.random() < .35) { bctx.translate(-.8, -.8); bctx.globalAlpha = .3; bctx.strokeStyle = "#e6eefa"; bctx.lineWidth = w * .35; bctx.stroke(); bctx.translate(.8, .8); }
    }
    bctx.globalAlpha = 1; bctx.fillStyle = "rgba(4,8,26,.24)"; bctx.fillRect(0, 0, W, H);
  }

  function newPart(p) {
    p = p || {}; p.x = Math.random() * W * 1.05 - W * .05; p.y = Math.random() * H * .78; p.age = 0; p.life = 3 + Math.random() * 5;
    p.spd = 14 + Math.random() * 22; p.w = 1.6 + Math.random() * 2.2;
    p.c = nearLight(p.x, p.y) ? 4 + ((Math.random() * 2) | 0) : (Math.random() < glowAt(p.x, p.y) ? (Math.random() * 2) | 0 : 1 + ((Math.random() * 3) | 0));
    return p;
  }

  function resize(w, h, dpr) {
    if (!el) return; W = w; H = h; DPR = Math.min(dpr || 1, 1.5);
    for (const c of [base, anim]) { c.width = Math.round(W * DPR); c.height = Math.round(H * DPR); }
    actx.setTransform(DPR, 0, 0, DPR, 0, 0); layout(); paintBase();
    const n = Math.max(80, Math.min(420, Math.round(W * H / 2600)));
    parts = Array.from({ length: n }, () => { const p = newPart(); p.age = Math.random() * p.life; return p; });
    draw(0);
  }

  function draw(dt) {
    if (!el) return;
    const t = performance.now() / 1000; actx.clearRect(0, 0, W, H); actx.lineCap = "round";
    // moving brush strokes that flow along the swirling field
    for (let ci = 0; ci < BLUES.length; ci++) {
      actx.strokeStyle = BLUES[ci];
      for (const p of parts) {
        if (p.c !== ci) continue;
        if (dt) { const a = field(p.x, p.y); p.x += Math.cos(a) * p.spd * dt; p.y += Math.sin(a) * p.spd * dt; p.age += dt;
          if (p.age > p.life || p.x > W + 20 || p.y < -20 || p.y > H) newPart(p); }
        let x = p.x, y = p.y; actx.beginPath(); actx.moveTo(x, y);
        for (let k = 0; k < 4; k++) { const a = field(x, y); x += Math.cos(a) * 6.5; y += Math.sin(a) * 6.5; actx.lineTo(x, y); }
        actx.globalAlpha = Math.sin(Math.PI * Math.min(1, p.age / p.life)) * .8; actx.lineWidth = p.w; actx.stroke();
      }
    }
    // haloed stars and the crescent moon (slowly turning, softly pulsing)
    actx.globalCompositeOperation = "lighter";
    for (const s of stars) {
      const k = 1 + .08 * Math.sin(t * s.sp + s.ph), sz = s.r * 2 * k;
      actx.globalAlpha = .82 + .18 * Math.sin(t * s.sp * 1.3 + s.ph);
      actx.save(); actx.translate(s.x, s.y); actx.rotate(t * .12 * (s.ph % 2 ? 1 : -1)); actx.drawImage(starSpr, -sz / 2, -sz / 2, sz, sz); actx.restore();
    }
    actx.globalCompositeOperation = "source-over";
    const mk = moon.r * 2 * (1 + .03 * Math.sin(t * .8)); actx.globalAlpha = 1;
    actx.save(); actx.translate(moon.x, moon.y); actx.rotate(Math.sin(t * .2) * .05); actx.drawImage(moonSpr, -mk, -mk, mk * 2, mk * 2); actx.restore();
    actx.globalAlpha = 1;
  }

  function mount(root, w, h, dpr) {
    el = root;
    root.innerHTML =
      '<canvas class="sky-base"></canvas><canvas class="sky-anim"></canvas><div class="en-shade"></div>' +
      '<div class="px p3"><img class="vil" src="assets/en/village.svg" alt=""></div>' +
      '<div class="px p2"><div class="hb h1"><div class="hbBob">' + HB(1) + '</div></div><div class="hb h2"><div class="hbBob">' + HB(2) + '</div></div></div>' +
      '<div class="px p4"><img class="cyp" src="assets/en/cypress.svg" alt=""></div>' +
      '<div class="px p5"><img class="flw fl" src="assets/en/flowers.svg" alt=""><img class="flw fr" src="assets/en/flowers.svg" alt=""></div>';
    base = root.querySelector(".sky-base"); anim = root.querySelector(".sky-anim");
    bctx = base.getContext("2d"); actx = anim.getContext("2d");
    starSpr = makeStarSprite(); moonSpr = makeMoonSprite(); resize(w, h, dpr);
  }
  window.__bgEn = { mount, resize, draw, get mounted() { return !!el; }, get canvas() { return anim; } };
})();
